t.script:
            
                document.addEventListener('DOMContentLoaded', function() {
                    const tenantId = """ + str(tenant.id) + """; // Odoo Inject
                    let progress = 10;
                    const progressBar = document.getElementById('provision-bar');
                    
                    // Simulasi Animasi Step (Agar terlihat 'Sibuk')
                    const steps = [
                        { p: 35, id: 'step-2' },
                        { p: 65, id: 'step-3' },
                        { p: 90, id: 'step-4' }
                    ];

                    let currentIdx = 0;
                    const interval = setInterval(() => {
                        if (currentIdx < steps.length) {
                            const step = steps[currentIdx];
                            progressBar.style.width = step.p + '%';
                            
                            const prevEl = document.getElementById('step-' + (currentIdx + 1));
                            if(prevEl) prevEl.classList.replace('text-primary','text-success');

                            const el = document.getElementById(step.id);
                            el.classList.replace('text-muted', 'text-primary');
                            el.querySelector('.fa').classList.remove('d-none');
                            
                            currentIdx++;
                        }
                    }, 4000);

                    // POLLING KE MASTER DB: Cek status asli
                    const checkStatus = setInterval(() => {
                        fetch('/workspace/status/' + """ + str(tenant.id) + """, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ params: {} })
                        }).then(r => r.json()).then(data => {
                            const res = data.result;
                            if (res.state === 'active') {
                                clearInterval(checkStatus);
                                clearInterval(interval); // Hentikan simulasi
                                
                                // Set 100%
                                progressBar.style.width = '100%';
                                progressBar.classList.remove('progress-bar-animated');
                                
                                // Show Launch Button
                                document.getElementById('ready-action').classList.remove('d-none');
                                document.getElementById('btn-launch').href = res.subdomain_url;
                            }
                        });
                    }, 3000); // Cek tiap 3 detik
                });
